"use strict";

const modules={
  simplex:{family:"Quy hoạch tuyến tính",algorithm:"Đơn hình thuận",title:"Thuật toán đơn hình",subtitle:"Di chuyển giữa các phương án cơ sở khả thi bằng phép pivot Gauss–Jordan.",visualTitle:"Hình học của bước pivot",visualCaption:"Mỗi cơ sở tương ứng với một đỉnh của đa diện khả thi",matrixTitle:"Bảng đơn hình",matrixCaption:"Cột vàng là biến vào; hàng vàng là biến ra",theory:`<h3>Điều kiện áp dụng</h3><p>Bản mô phỏng giải bài toán <b>Max</b>, các ràng buộc dạng ≤, RHS không âm và x ≥ 0.</p><h3>Quy tắc pivot</h3><p>Chọn cột có <b>cⱼ−zⱼ dương lớn nhất</b>. Hàng ra được chọn bằng tỷ số nhỏ nhất <b>bᵢ/aᵢⱼ</b> với aᵢⱼ &gt; 0. Tối ưu khi mọi cⱼ−zⱼ ≤ 0.</p>`},
  dual_simplex:{family:"Quy hoạch tuyến tính",algorithm:"Đơn hình đối ngẫu",title:"Thuật toán đơn hình đối ngẫu",subtitle:"Giữ tính khả thi đối ngẫu trong khi loại dần các RHS âm.",visualTitle:"Khôi phục tính khả thi thuận",visualCaption:"Chọn hàng RHS âm nhất trước khi pivot",matrixTitle:"Bảng đơn hình đối ngẫu",matrixCaption:"Hàng vàng có RHS âm; cột vàng thỏa quy tắc tỷ số đối ngẫu",theory:`<h3>Bất biến</h3><p>Đơn hình đối ngẫu bắt đầu với <b>cⱼ−zⱼ ≤ 0</b> nhưng còn RHS âm. Chọn hàng ra có RHS âm nhất.</p><h3>Cột vào</h3><p>Trong hàng ra, xét các hệ số âm và chọn tỷ số phù hợp để sau pivot vẫn giữ tính khả thi đối ngẫu. Dừng khi mọi RHS ≥ 0.</p>`},
  integer_bb:{family:"Quy hoạch nguyên",algorithm:"Nhánh & Cận",title:"Quy hoạch nguyên bằng Nhánh & Cận",subtitle:"Giải thư giãn LP, phân nhánh tại biến phân số và cắt bằng cận trên.",visualTitle:"Cây Nhánh & Cận nguyên",visualCaption:"Mỗi nhánh thêm một ràng buộc floor/ceil",matrixTitle:"Các nút LP relaxation",matrixCaption:"Nghiệm phân số, cận và trạng thái của từng nút",theory:`<h3>Thư giãn LP</h3><p>Bỏ điều kiện nguyên để lấy cận trên cho bài toán Max. Nếu nghiệm LP nguyên thì cập nhật nghiệm tốt nhất.</p><h3>Phân nhánh</h3><p>Với xₖ* phân số, tạo hai nút <b>xₖ ≤ floor(xₖ*)</b> và <b>xₖ ≥ ceil(xₖ*)</b>. Cắt nút vô nghiệm hoặc có cận không tốt hơn incumbent.</p>`},
  geo_bounded:{family:"Hình học LP",algorithm:"Miền phương án kín",title:"Hình học — miền phương án bị chặn",subtitle:"Dựng miền khả thi, tính giao điểm, đánh giá từng đỉnh và di chuyển đường mức.",visualTitle:"Miền khả thi và đường mức",visualCaption:"Đường vàng dịch theo hướng tăng của hàm mục tiêu",matrixTitle:"Bảng đánh giá các đỉnh",matrixCaption:"Định lý cơ bản LP: tối ưu hữu hạn đạt tại một đỉnh",theory:`<h3>Quy trình</h3><ol><li>Đổi bất phương trình thành đường biên.</li><li>Tính giao điểm từng cặp đường và hai trục.</li><li>Lọc các điểm thỏa toàn bộ ràng buộc.</li><li>Tính Z tại mỗi đỉnh và tịnh tiến đường mức.</li></ol>`},
  geo_unbounded:{family:"Hình học LP",algorithm:"Miền không bị chặn",title:"Hình học — miền phương án không bị chặn",subtitle:"Phân biệt miền khả thi không bị chặn với hàm mục tiêu không bị chặn.",visualTitle:"Miền khả thi mở và tia tăng",visualCaption:"Mũi tên biểu diễn hướng khả thi đi ra vô hạn",matrixTitle:"Đỉnh và hướng vô hạn",matrixCaption:"Miền mở vẫn có thể có hoặc không có tối ưu hữu hạn",theory:`<h3>Hai khái niệm khác nhau</h3><p>Miền khả thi không bị chặn không tự động có nghĩa bài toán vô hạn. Bài toán Max chỉ vô hạn nếu tồn tại một hướng khả thi d với <b>c·d &gt; 0</b>.</p>`},
  transport:{family:"Vận tải",algorithm:"Phương pháp chi phí thấp nhất",title:"Bài toán vận tải",subtitle:"Phân phối hàng hóa sao cho thỏa cung–cầu và giảm tổng chi phí vận chuyển.",visualTitle:"Mạng lưới vận chuyển",visualCaption:"Hạt sáng biểu diễn tuyến đang được phân bổ",matrixTitle:"Ma trận chi phí và phân bổ",matrixCaption:"Số lớn: chi phí · Số góc: lượng phân bổ",theory:`<h3>Mô hình</h3><p>Tìm <b>xᵢⱼ ≥ 0</b> để tối thiểu hóa <b>Z = ΣᵢΣⱼ cᵢⱼxᵢⱼ</b>, đồng thời tổng lượng rời mỗi nguồn bằng cung và tổng lượng đến mỗi nơi nhận bằng cầu.</p><h3>Phương pháp chi phí thấp nhất</h3><ol><li>Chọn ô còn mở có chi phí nhỏ nhất.</li><li>Phân bổ min(cung còn lại, cầu còn lại).</li><li>Đóng hàng hoặc cột đã hết và lặp lại.</li></ol><p><b>Lưu ý:</b> Đây là phương pháp tạo phương án khả thi ban đầu, chưa đảm bảo tối ưu toàn cục. Cần MODI/Stepping-stone để kiểm tra và cải thiện.</p>`},
  northwest:{family:"Vận tải",algorithm:"Phương pháp Góc Tây Bắc",title:"Phương pháp Góc Tây Bắc",subtitle:"Tạo phương án khả thi ban đầu chỉ từ cung–cầu, bắt đầu ở ô trên cùng bên trái.",visualTitle:"Tiến trình phân bổ Tây Bắc",visualCaption:"Đường vàng là ô đang phân bổ",matrixTitle:"Ma trận phân bổ Góc Tây Bắc",matrixCaption:"Phương pháp không sử dụng chi phí khi chọn ô",theory:`<h3>Quy tắc</h3><p>Bắt đầu tại ô góc trên bên trái, phân bổ <b>min(cung, cầu)</b>. Nếu hết cung thì đi xuống; nếu hết cầu thì đi sang phải.</p><p><b>Giới hạn:</b> Phương pháp luôn tạo phương án khả thi cho bài toán cân bằng nhưng không xét chi phí, vì vậy kết quả ban đầu có thể xa tối ưu.</p>`},
  modi:{family:"Vận tải",algorithm:"Phương pháp Thế vị MODI",title:"Kiểm tra và cải thiện bằng MODI",subtitle:"Tính thế vị uᵢ, vⱼ và chi phí cơ hội để cải thiện phương án vận tải.",visualTitle:"Chu trình cải thiện MODI",visualCaption:"Tuyến vàng vào cơ sở; phân bổ được điều chỉnh theo chu trình ±",matrixTitle:"Chi phí cơ hội và phân bổ",matrixCaption:"Δᵢⱼ = cᵢⱼ − uᵢ − vⱼ",theory:`<h3>Điều kiện tối ưu</h3><p>Với các ô cơ sở, giải <b>uᵢ + vⱼ = cᵢⱼ</b>. Ở ô ngoài cơ sở tính <b>Δᵢⱼ = cᵢⱼ − uᵢ − vⱼ</b>. Bài toán cực tiểu tối ưu khi mọi Δᵢⱼ ≥ 0.</p><h3>Cải thiện</h3><p>Chọn ô có Δ âm nhất, lập chu trình kín xen kẽ dấu +/− và dịch lượng θ bằng giá trị nhỏ nhất tại các ô dấu −.</p>`},
  assignment:{family:"Phân công",algorithm:"Thuật toán Hungarian",title:"Bài toán phân công",subtitle:"Ghép mỗi nhân sự với đúng một công việc để tổng chi phí là nhỏ nhất.",visualTitle:"Ghép nhân sự – công việc",visualCaption:"Đường sáng là phép ghép đang được xác nhận",matrixTitle:"Ma trận biến đổi Hungarian",matrixCaption:"Theo dõi phép trừ hàng, trừ cột và các số 0",theory:`<h3>Mô hình</h3><p>Biến nhị phân <b>xᵢⱼ ∈ {0,1}</b>. Mỗi người nhận đúng một việc, mỗi việc có đúng một người. Mục tiêu: <b>min ΣᵢΣⱼ cᵢⱼxᵢⱼ</b>.</p><h3>Vì sao phép trừ không đổi nghiệm?</h3><p>Mọi phương án đều chọn đúng một phần tử ở mỗi hàng và mỗi cột. Trừ cùng một hằng số khỏi một hàng/cột làm chi phí của mọi phương án giảm cùng lượng, nên thứ tự tối ưu không đổi.</p>`},
  assignment_bb:{family:"Phân công",algorithm:"Nhánh & Cận",title:"Phân công tác vụ bằng Nhánh & Cận",subtitle:"Xây cây quyết định, dùng cận dưới để loại các nhánh không thể tốt hơn nghiệm hiện tại.",visualTitle:"Cây tìm kiếm phân công",visualCaption:"Mỗi tầng gán thêm một nhân sự",matrixTitle:"Ma trận chi phí phân công",matrixCaption:"Ô vàng thuộc phương án đang mở rộng",theory:`<h3>Nhánh</h3><p>Ở tầng i, thử gán nhân sự i cho từng công việc chưa được dùng.</p><h3>Cận dưới</h3><p>Cận = chi phí đã gán + tổng chi phí nhỏ nhất khả dụng của từng hàng còn lại. Nếu cận không nhỏ hơn nghiệm tốt nhất hiện có, nhánh được cắt an toàn.</p>`},
  dijkstra:{family:"Mạng lưới",algorithm:"Thuật toán Dijkstra",title:"Đường đi ngắn nhất",subtitle:"Tìm tổng trọng số nhỏ nhất từ đỉnh nguồn đến mọi đỉnh còn lại.",visualTitle:"Đồ thị có trọng số",visualCaption:"Vòng sáng là đỉnh đang xét; cạnh vàng vừa được nới lỏng",matrixTitle:"Khoảng cách tạm thời",matrixCaption:"d(v) và đỉnh trước trên đường đi tốt nhất",theory:`<h3>Điều kiện áp dụng</h3><p>Dijkstra đúng khi mọi trọng số cạnh <b>không âm</b>. Nếu có cạnh âm, dùng Bellman–Ford.</p><h3>Bất biến tham lam</h3><p>Khi chọn đỉnh chưa cố định có khoảng cách tạm thời nhỏ nhất, không đường đi nào qua các đỉnh còn lại có thể làm nó nhỏ hơn, vì trọng số đều không âm.</p>`},
  tsp_nn:{family:"TSP",algorithm:"Lân cận gần nhất",title:"TSP — Lân cận gần nhất",subtitle:"Từ thành phố hiện tại, luôn đi đến thành phố chưa thăm gần nhất.",visualTitle:"Hành trình tham lam",visualCaption:"Cạnh vàng là lựa chọn gần nhất ở bước hiện tại",matrixTitle:"Ma trận khoảng cách",matrixCaption:"Khoảng cách Euclid làm tròn đến 1 chữ số",theory:`<h3>Quy tắc tham lam</h3><p>Chọn một thành phố xuất phát, lặp lại việc đi tới thành phố chưa thăm gần nhất rồi quay về điểm đầu.</p><p><b>Giới hạn:</b> Thuật toán nhanh nhưng không bảo đảm tối ưu. Kết quả phụ thuộc thành phố xuất phát.</p>`},
  tsp_ga:{family:"TSP",algorithm:"Thuật toán di truyền",title:"TSP — Thuật toán di truyền",subtitle:"Tiến hóa quần thể hành trình bằng chọn lọc, lai ghép, đột biến và tinh hoa.",visualTitle:"Tiến hóa hành trình",visualCaption:"Đường cyan là cá thể tốt nhất của thế hệ",matrixTitle:"Quần thể và độ thích nghi",matrixCaption:"Fitness = 1 / chiều dài hành trình",theory:`<h3>Mã hóa</h3><p>Mỗi nhiễm sắc thể là một hoán vị các thành phố. Độ thích nghi tỉ lệ nghịch với tổng chiều dài chu trình.</p><h3>Toán tử</h3><p>Bản mô phỏng dùng chọn lọc giải đấu, lai ghép có thứ tự OX, đột biến đổi chỗ và giữ lại cá thể tinh hoa. Seed cố định giúp tái hiện cùng kết quả.</p><p><b>Lưu ý:</b> GA là metaheuristic, không chứng minh nghiệm toàn cục.</p>`}
};

